def refine(D):
 for l,d in D.items():
  d.update(COPY[l])
  d['fallbackbusiness'] = d['fallback']+' '+d['conflict']
  # Retain FAQ facts but replace inherited furniture-first pricing/scope answers.
  d['faq']=[(q,a) for q,a in d['faq'] if not any(x in a for x in ('Zakres i wycenę mebli','Scope and pricing for furniture','Umfang und Preis für Möbel'))]
  q={'pl':'Czy mogę powierzyć Ci cały projekt, nie tylko meble?','en':'Can you manage the whole project, not only furniture?','de':'Können Sie das gesamte Projekt und nicht nur Möbel betreuen?'}[l]
  d['faq'].insert(0,(q,d['forbusinesslead']+' '+d['new']))
 return D

